import sys

def main():
    import sys
    import sys
    MOD = 10**9 + 7
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    parent = list(range(n))
    size = [1] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if size[rootX] < size[rootY]:
                rootX, rootY = rootY, rootX
            parent[rootY] = rootX
            size[rootX] += size[rootY]
            size[rootY] = 0

    for i in range(n):
        union(i, a[i] - 1)

    result = 1
    for s in size:
        if s > 0:
            result = (result * (1 << s)) % MOD

    print(result)

if __name__ == "__main__":
    main()
